--
-- Triggers `merit_calls`
--
DELIMITER $$
CREATE TRIGGER `trg_merit_call_requires_previous_migration` BEFORE INSERT ON `merit_calls` FOR EACH ROW BEGIN
    IF NEW.call_number > 1 THEN

        IF NOT EXISTS (
            SELECT 1
            FROM merit_calls previous_call
            WHERE previous_call.academic_year = NEW.academic_year
              AND previous_call.call_number = NEW.call_number - 1
              AND previous_call.process_closed_at IS NOT NULL
              AND previous_call.migration_processed_at IS NOT NULL
        ) THEN
            SIGNAL SQLSTATE '45000'
            SET MESSAGE_TEXT =
                'Previous Merit Call must be closed and Migration processed before publishing the next Merit Call.';
        END IF;

    END IF;
END
$$
DELIMITER ;

